<span class="line">        <span class="token keyword">const</span> canvas <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">OffscreenCanvas</span><span class="token punctuation">(</span>sample<span class="token punctuation">.</span>displayWidth<span class="token punctuation">,</span> sample<span class="token punctuation">.</span>displayHeight<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
